-- Backend Engineering ("The Fracture") Act 22 -- "Performance & Scale" content.
-- Opens Arc VI (Scale). 1 campaign, 2 operations, 12 missions (11 lessons +
-- boss). Same campaigns -> operations -> missions -> dialogue -> objectives
-- -> challenges -> hints pattern as every world. The acts/worlds rows for
-- act-be-5 / world-be-22 already exist (20260810260000); this migration
-- only adds mission content.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be22', 'world-be-22', 'performance-and-scale', '22A - Performance & Scale', 'A public event page goes viral overnight, and the service that was fine for a normal Tuesday falls over within four minutes of real traffic. Learn to measure and diagnose slowness before you try to scale your way out of it.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be22-1', 'campaign-be22', 'measuring-the-damage', 'Measuring the Damage', 'What latency, throughput and percentiles actually measure, how to profile a slow request down to the exact function, and why bigger hardware does not always fix what is actually wrong.', 1),
  ('operation-be22-2', 'campaign-be22', 'scaling-out-for-real', 'Scaling Out For Real', 'Adding more instances instead of a bigger one, the statelessness it quietly requires, how a load balancer and its health checks keep that fleet honest, and planning capacity before the next flash crowd instead of during it.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be22-01', 'world-be-22', 'campaign-be22', 'operation-be22-1', 'latency', 'Latency', 'The event page took 8 seconds to load for users who used to see it in 200 milliseconds -- and not one request actually failed.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"latency-breakdown-sim"}'::jsonb, '{"xp":260,"credits":50}'::jsonb, false, 1),
  ('mission-be22-02', 'world-be-22', 'campaign-be22', 'operation-be22-1', 'throughput', 'Throughput', 'Per-request processing time never changed during the incident. What changed was how many requests were trying to get through at once.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be22-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"throughput-ceiling-sim"}'::jsonb, '{"xp":262,"credits":50}'::jsonb, false, 2),
  ('mission-be22-03', 'world-be-22', 'campaign-be22', 'operation-be22-1', 'percentiles', 'Percentiles', 'The average looked fine at 340ms. It was hiding the 1% of requests that took 9 seconds, and that 1% is who filed the complaints.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be22-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"percentile-reading-sim"}'::jsonb, '{"xp":264,"credits":51}'::jsonb, false, 3),
  ('mission-be22-04', 'world-be-22', 'campaign-be22', 'operation-be22-1', 'profiling', 'Profiling', 'Nobody had looked at a profile in months. If they had, the incident would not have been a surprise.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be22-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"cpu-profiling-sim"}'::jsonb, '{"xp":266,"credits":51}'::jsonb, false, 4),
  ('mission-be22-05', 'world-be-22', 'campaign-be22', 'operation-be22-1', 'cpu-vs-io-bottlenecks', 'CPU vs I/O Bottlenecks', 'The slowest function was not the CPU crunching numbers. It was the server sitting idle, waiting on the database to answer.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be22-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"cpu-io-bottleneck-sim"}'::jsonb, '{"xp":268,"credits":51}'::jsonb, false, 5),
  ('mission-be22-06', 'world-be-22', 'campaign-be22', 'operation-be22-1', 'vertical-scaling', 'Vertical Scaling', 'Buy a bigger box: the simplest fix anyone reaches for under pressure, and one with a ceiling nobody mentions until they hit it.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be22-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"vertical-scaling-sim"}'::jsonb, '{"xp":270,"credits":52}'::jsonb, false, 6),
  ('mission-be22-07', 'world-be-22', 'campaign-be22', 'operation-be22-2', 'horizontal-scaling', 'Horizontal Scaling', 'Do not make the one box bigger -- add more boxes, and spread the traffic across all of them. In theory.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be22-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"horizontal-scaling-sim"}'::jsonb, '{"xp":272,"credits":52}'::jsonb, false, 7),
  ('mission-be22-08', 'world-be-22', 'campaign-be22', 'operation-be22-2', 'stateless-services', 'Stateless Services', 'Horizontal scaling was quietly counting on a requirement nobody wrote down: no instance should remember a user by itself.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be22-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"stateless-services-sim"}'::jsonb, '{"xp":274,"credits":52}'::jsonb, false, 8),
  ('mission-be22-09', 'world-be-22', 'campaign-be22', 'operation-be22-2', 'load-balancers', 'Load Balancers', 'Something has to actually decide which instance gets each request, and it has more than one way to make that call.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be22-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"load-balancer-sim"}'::jsonb, '{"xp":276,"credits":53}'::jsonb, false, 9),
  ('mission-be22-10', 'world-be-22', 'campaign-be22', 'operation-be22-2', 'health-checks', 'Health Checks', 'Being in the pool is not the same as being able to serve traffic. Nothing enforces that difference except a health check.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be22-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"health-check-sim"}'::jsonb, '{"xp":278,"credits":53}'::jsonb, false, 10),
  ('mission-be22-11', 'world-be-22', 'campaign-be22', 'operation-be22-2', 'capacity-planning', 'Capacity Planning', 'How much traffic can this system actually take, and how much headroom above normal load survives the next spike?', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be22-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"capacity-planning-sim"}'::jsonb, '{"xp":280,"credits":54}'::jsonb, false, 11),
  ('mission-be22-12', 'world-be-22', 'campaign-be22', 'operation-be22-2', 'flash-crowd', 'Flash Crowd', 'Scaled out to a dozen instances and users are still losing their carts mid-checkout -- scaling out did not cause it, it exposed it.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be22-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"flash-crowd-boss-sim"}'::jsonb, '{"xp":600,"credits":140,"badgeIds":["flash-crowd"],"skillXp":{"performance_and_scale":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be22-01', 1, 'mira', 'New Arc. Everything Forge has built survives contact with reality one piece at a time now -- tested, hardened, proven. Nobody has asked yet what happens when it all has to work together, under real load.'),
  ('mission-be22-01', 2, 'forge', 'Found out the hard way. A public event page went viral overnight. The box behind it was fine on a normal Tuesday. It fell over in four minutes flat once real traffic showed up.'),
  ('mission-be22-01', 3, 'forge', 'Nothing crashed outright at first. Requests kept succeeding. They just kept taking longer, and longer, until "succeeding" stopped meaning anything to the people waiting on them.'),
  ('mission-be22-01', 4, 'mira', 'That is where we start. Before scale, before fixes -- the actual vocabulary for "slow." First word: latency.'),
  ('mission-be22-02', 1, 'mira', 'Latency answers "how long did one request take." Throughput answers something different: how many requests can this system finish per second, sustained -- and the two numbers can move independently.'),
  ('mission-be22-02', 2, 'mira', 'The event page''s own per-request processing time barely changed during the incident. What changed was how many requests were trying to get through at once. Past what the system can sustain, extra requests do not get slower -- they just wait, and that wait is what turned into the four-minute latency spike.'),
  ('mission-be22-03', 1, 'forge', 'Someone is about to tell you the average response time during the incident was 340ms and that it "does not look that bad." Do not believe the average.'),
  ('mission-be22-03', 2, 'forge', 'An average hides exactly the users it should be warning you about. A handful of requests taking 9 seconds barely move a mean calculated across ten thousand fast ones. Percentiles do not let that hide: p99 means the slowest 1% -- and at real volume, that is still thousands of actual people.'),
  ('mission-be22-04', 1, 'mira', 'Guessing what is slow wastes more time than the slowness itself. A profiler tells you, function by function, exactly where the time actually went.'),
  ('mission-be22-04', 2, 'mira', 'During the incident, one function alone accounted for nearly all of it. Nobody had looked at a profile in months. If they had, this would not have been a surprise at minute four.'),
  ('mission-be22-05', 1, 'forge', 'Once you know where the time goes, you still need to know what kind of wait it is. A CPU-bound bottleneck and an I/O-bound bottleneck get fixed in completely different ways -- and confusing them wastes an afternoon.'),
  ('mission-be22-05', 2, 'forge', 'That function was not the CPU crunching numbers. It was the server sitting there, doing nothing, waiting on the database to answer. Nothing about adding processing power was ever going to fix that.'),
  ('mission-be22-06', 1, 'mira', 'Simplest fix anyone reaches for under pressure: buy a bigger box. More CPU, more RAM, same architecture. That is vertical scaling, and it works, right up until it does not.'),
  ('mission-be22-06', 2, 'mira', 'There is a ceiling on how big one machine gets, it costs disproportionately more near the top of that range, the whole service still lives or dies with that one box -- and it does nothing for a bottleneck that was never about raw capacity in the first place.'),
  ('mission-be22-07', 1, 'forge', 'The other lever: do not make the one box bigger, add more boxes, and spread the traffic across all of them. In theory, three identical instances handle roughly three times what one instance could.'),
  ('mission-be22-07', 2, 'forge', 'In theory. It only works cleanly if every instance is actually interchangeable -- if any one of them can answer any request, with nothing about the answer depending on which specific box happened to receive it.'),
  ('mission-be22-08', 1, 'mira', 'That is the requirement horizontal scaling was quietly counting on: statelessness. No instance should remember anything about a specific user between one request and the next, not in its own local memory.'),
  ('mission-be22-08', 2, 'mira', 'The moment a service stashes something like a session or a cart in a variable that lives only inside one running process, it stops being interchangeable. Route that user to a different instance next time, and their data is just gone.'),
  ('mission-be22-09', 1, 'forge', 'Something has to actually decide which instance gets each request. That is the load balancer''s whole job, and it has more than one way to make that call.'),
  ('mission-be22-09', 2, 'forge', 'Round robin, least connections, IP hash -- pick the wrong algorithm for your traffic shape and three "balanced" instances can end up anything but.'),
  ('mission-be22-10', 1, 'mira', 'Adding an instance to the pool does not mean it is actually able to serve traffic yet. A health check is the load balancer periodically asking each instance, directly: are you actually okay?'),
  ('mission-be22-10', 2, 'mira', 'Skip that, and a load balancer will happily keep sending real users to an instance that is frozen, out of memory, or mid-crash -- because nothing ever told it to stop.'),
  ('mission-be22-11', 1, 'forge', 'Before the next viral event page, someone has to answer the question in advance: how much traffic can this system actually take, and how much headroom above normal load do we need to survive a spike?'),
  ('mission-be22-11', 2, 'forge', 'That means real numbers -- peak concurrent users, requests per user, what a single instance can sustainably handle -- not a guess made under pressure at minute four of an outage.'),
  ('mission-be22-12', 1, 'mira', 'The event page is live again, scaled out to a dozen instances behind a load balancer. Should be able to take anything now.'),
  ('mission-be22-12', 2, 'forge', 'Should have. Users are getting logged out mid-checkout, carts disappearing between page loads, all at random -- and it started the moment we scaled out, not before.'),
  ('mission-be22-12', 3, 'mira', 'Walk me through it. What actually breaks when you add more replicas to a service that was not ready for it?'),
  ('mission-be22-12', 4, 'forge', '...found it. This service has been keeping every user''s session and cart in local memory this whole time. Scaling out did not create the problem -- it just made twelve different, disagreeing versions of it exist at once.'),
  ('mission-be22-12', 5, 'mira', 'So scaling out worked exactly as designed. It just exposed a design that was never actually ready to be scaled.'),
  ('mission-be22-12', 6, 'forge', '...one more thing, while I had the capacity-planning spreadsheet open for this incident. The row label for our whole target metric reads "requests//sec." Not a one-off -- it is in every capacity template we have used, going back further than I can trace tonight.'),
  ('mission-be22-12', 7, 'mira', 'Noted. File it. Fix the statelessness problem first -- that one is costing us checkouts right now. We will come back to the spreadsheet.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be22-01-o1', 'mission-be22-01', 1, 'Define latency', 'Explain what latency actually measures, and what it does not.'),
  ('mission-be22-01-o2', 'mission-be22-01', 2, 'Break down the delay', 'Identify where each stage of a request''s total latency actually accumulates.'),
  ('mission-be22-02-o1', 'mission-be22-02', 1, 'Tell latency and throughput apart', 'Explain why total wait time grew even though per-request processing time never changed.'),
  ('mission-be22-02-o2', 'mission-be22-02', 2, 'Find the ceiling', 'Identify which evidence actually shows the throughput ceiling being hit.'),
  ('mission-be22-03-o1', 'mission-be22-03', 1, 'Distrust the average', 'Decide which statistic actually reveals the incident''s real damage.'),
  ('mission-be22-03-o2', 'mission-be22-03', 2, 'Read the percentile table', 'Find the percentile that explains a real but minority set of complaints.'),
  ('mission-be22-04-o1', 'mission-be22-04', 1, 'Read the profile', 'Find the exact function a slow request''s time actually went to.'),
  ('mission-be22-05-o1', 'mission-be22-05', 1, 'Classify the bottleneck', 'Decide whether this bottleneck is CPU-bound or I/O-bound, using the evidence.'),
  ('mission-be22-05-o2', 'mission-be22-05', 2, 'Pick the right fix', 'Choose the fix that actually addresses an I/O-bound bottleneck.'),
  ('mission-be22-06-o1', 'mission-be22-06', 1, 'Test the fix', 'Decide whether vertical scaling would actually fix this specific bottleneck.'),
  ('mission-be22-06-o2', 'mission-be22-06', 2, 'Name the structural risk', 'Identify the risk of vertical scaling beyond not fixing this bottleneck.'),
  ('mission-be22-07-o1', 'mission-be22-07', 1, 'Name the hidden requirement', 'Identify what horizontal scaling requires that vertical scaling never had to.'),
  ('mission-be22-07-o2', 'mission-be22-07', 2, 'Order the scale-out', 'Put the steps of safely adding a new instance in the right order.'),
  ('mission-be22-08-o1', 'mission-be22-08', 1, 'Find the local state', 'Find the line that stores per-user state in a single instance''s memory.'),
  ('mission-be22-08-o2', 'mission-be22-08', 2, 'Choose the real fix', 'Pick the fix that actually makes state visible to every instance.'),
  ('mission-be22-09-o1', 'mission-be22-09', 1, 'Match the algorithm', 'Match each load balancing algorithm to what it actually does.'),
  ('mission-be22-10-o1', 'mission-be22-10', 1, 'Find the gap', 'Identify why a failing instance is still receiving a full share of traffic.'),
  ('mission-be22-11-o1', 'mission-be22-11', 1, 'Do the math', 'Calculate how many instances are actually needed for a projected spike with headroom.'),
  ('mission-be22-12-o1', 'mission-be22-12', 1, 'Diagnose the failure', 'Identify the evidence that points at the actual root cause, not just a symptom.'),
  ('mission-be22-12-o2', 'mission-be22-12', 2, 'Reject the wrong fixes', 'Pick the one fix among plausible alternatives that actually addresses local per-instance state.'),
  ('mission-be22-12-o3', 'mission-be22-12', 3, 'Confirm the fix holds', 'Determine whether a proposed patch actually solves the statelessness problem.'),
  ('mission-be22-12-o4', 'mission-be22-12', 4, 'Close the incident', 'State the actual root cause and the fix, not any of the tempting workarounds.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be22-01-o1-c1', 'mission-be22-01-o1', 1, 'multiple_choice', 'A request to the event page took 8,000ms instead of its usual 200ms, but it still returned a correct 200 OK. What actually happened?', '{"question":"A request to the event page took 8,000ms instead of its usual 200ms, but it still returned a correct 200 OK. What actually happened?","options":[{"id":"a","text":"Nothing meaningful -- slow is the same as down"},{"id":"b","text":"This is elevated latency, not downtime -- the request still completed successfully, it just took far longer to do it"},{"id":"c","text":"This is specifically a throughput failure"},{"id":"d","text":"This can only be TLS renegotiation overhead"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be22-01-o2-c1', 'mission-be22-01-o2', 1, 'drag_and_drop', 'Sort each step of a request into where its latency actually accumulates.', '{"items":[{"id":"i1","text":"The request travels across the network to the server"},{"id":"i2","text":"The request waits in line behind other requests already being handled"},{"id":"i3","text":"The server actually computes the response"},{"id":"i4","text":"The response travels back across the network to the client"}],"targets":[{"id":"t1","label":"Network transit (out)"},{"id":"t2","label":"Queueing delay"},{"id":"t3","label":"Processing time"},{"id":"t4","label":"Network transit (return)"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-be22-02-o1-c1', 'mission-be22-02-o1', 1, 'multiple_choice', 'The event page''s own processing time never changed -- each request still took 200ms once it started. But four minutes in, users were waiting 8 seconds. What actually happened?', '{"question":"The event page''s own processing time never changed -- each request still took 200ms once it started. But four minutes in, users were waiting 8 seconds. What actually happened?","options":[{"id":"a","text":"Processing got slower for every request"},{"id":"b","text":"The system hit its throughput ceiling -- it could only start so many requests at once, so new ones queued, and queueing time is what pushed total latency up, not slower processing"},{"id":"c","text":"This is purely a network latency issue"},{"id":"d","text":"Throughput and latency are the same measurement"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be22-02-o2-c1', 'mission-be22-02-o2', 1, 'investigation', 'Which evidence explains why total wait time exploded even though processing time did not change?', '{"evidence":[{"id":"ev1","label":"Per-request processing time, sampled","detail":"195-210ms throughout the incident, no meaningful change"},{"id":"ev2","label":"Requests-in-flight graph","detail":"Climbed from 40 to 3,800 over the four-minute incident window"},{"id":"ev3","label":"Client TLS versions","detail":"Unchanged across the entire incident"}],"question":"Which evidence explains why total wait time exploded even though processing time did not change?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be22-03-o1-c1', 'mission-be22-03-o1', 1, 'multiple_choice', 'Average latency during the incident was 340ms. p99 was 9,200ms. Which number should actually worry you, and why?', '{"question":"Average latency during the incident was 340ms. p99 was 9,200ms. Which number should actually worry you, and why?","options":[{"id":"a","text":"340ms, since it is the overall average"},{"id":"b","text":"9,200ms -- 1% of requests is still thousands of real users at this volume, and averages mathematically bury a long tail like that"},{"id":"c","text":"Neither, only the error rate matters"},{"id":"d","text":"They should always be equal in a healthy system"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be22-03-o2-c1', 'mission-be22-03-o2', 1, 'investigation', 'The support queue is full of complaints from a small but real fraction of users. Which figure actually explains that?', '{"evidence":[{"id":"ev1","label":"p50","detail":"210ms"},{"id":"ev2","label":"p95","detail":"480ms"},{"id":"ev3","label":"p99","detail":"9,400ms"}],"question":"The support queue is full of complaints from a small but real fraction of users. Which figure actually explains that?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be22-04-o1-c1', 'mission-be22-04-o1', 1, 'code_debugging', 'Which line in this profile is actually where the request''s 8.2 seconds went?', '{"language":"text","code":"handleEventPageRequest -- 8210ms total\n  renderEventTemplate -- 120ms\n  fetchAttendeeCount -- 7890ms\n    queryAttendeesTable -- 7860ms\n  serializeResponse -- 40ms","question":"Which line in this profile is actually where the request''s 8.2 seconds went?"}'::jsonb, '{"requiredLineIds":["    queryAttendeesTable -- 7860ms"]}'::jsonb),

  ('mission-be22-05-o1-c1', 'mission-be22-05-o1', 1, 'investigation', 'Is this bottleneck CPU-bound or I/O-bound, and which evidence proves it?', '{"evidence":[{"id":"ev1","label":"CPU utilization during the slow request","detail":"4%"},{"id":"ev2","label":"Time spent waiting on the database connection","detail":"7,860ms out of 7,890ms total"},{"id":"ev3","label":"Memory usage","detail":"Stable, no swapping"}],"question":"Is this bottleneck CPU-bound or I/O-bound, and which evidence proves it?"}'::jsonb, '{"requiredEvidenceIds":["ev1","ev2"]}'::jsonb),
  ('mission-be22-05-o2-c1', 'mission-be22-05-o2', 1, 'multiple_choice', 'Given this is I/O-bound, not CPU-bound, which fix actually addresses it?', '{"question":"Given this is I/O-bound, not CPU-bound, which fix actually addresses it?","options":[{"id":"a","text":"Add more CPU cores to the box"},{"id":"b","text":"Fix the query or connection path causing the wait (a missing index, connection pool exhaustion, a slow downstream call) -- more CPU does not help a process that is just waiting"},{"id":"c","text":"Upgrade to a faster CPU clock speed"},{"id":"d","text":"Enable CPU pinning"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be22-06-o1-c1', 'mission-be22-06-o1', 1, 'multiple_choice', 'The event page''s bottleneck is I/O wait on a database call. Would doubling the app server''s CPU and RAM (vertical scaling) fix it?', '{"question":"The event page''s bottleneck is I/O wait on a database call. Would doubling the app server''s CPU and RAM (vertical scaling) fix it?","options":[{"id":"a","text":"Yes, more resources always help"},{"id":"b","text":"No -- the app server is not the one that is the bottleneck; it is idle, waiting on the database, so giving it more CPU or RAM does not touch the actual wait"},{"id":"c","text":"Yes, but only if the service is also restarted"},{"id":"d","text":"No, because vertical scaling is never possible on cloud infrastructure"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be22-06-o2-c1', 'mission-be22-06-o2', 1, 'investigation', 'Beyond not fixing this specific bottleneck, what is the other structural risk of continuing to scale this service vertically?', '{"evidence":[{"id":"ev1","label":"Largest available instance size in this box family","detail":"2x more CPU/RAM than current, priced 3.5x higher"},{"id":"ev2","label":"Production traffic distribution","detail":"This single box is serving 100% of production traffic"},{"id":"ev3","label":"Vertical scaling procedure","detail":"Requires a restart, which drops all in-flight connections"}],"question":"Beyond not fixing this specific bottleneck, what is the other structural risk of continuing to scale this service vertically?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be22-07-o1-c1', 'mission-be22-07-o1', 1, 'multiple_choice', 'What does horizontal scaling require that vertical scaling never had to worry about?', '{"question":"What does horizontal scaling require that vertical scaling never had to worry about?","options":[{"id":"a","text":"Nothing extra -- it is a drop-in replacement for a bigger box"},{"id":"b","text":"That any instance can serve any request -- which only holds if instances do not depend on state that only exists on one specific box"},{"id":"c","text":"A faster CPU clock speed per instance"},{"id":"d","text":"Removing the database entirely"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be22-07-o2-c1', 'mission-be22-07-o2', 1, 'interactive_diagram', 'Order the steps to safely add a new instance to a scaled-out service.', '{"diagramId":"horizontal-scale-out-sequence","hotspots":[{"id":"provision","label":"Provision a new instance","explanation":"A new, identical copy of the service starts up."},{"id":"register","label":"Register it with the load balancer","explanation":"The distributor adds it to the pool of instances eligible to receive requests, though it may still be marked unhealthy."},{"id":"health_check","label":"Instance passes its health check","explanation":"The load balancer confirms the instance is actually able to serve traffic."},{"id":"traffic","label":"Instance begins receiving live traffic","explanation":"Only now does real user traffic actually reach it."}],"task":"Order the steps to safely add a new instance to a scaled-out service."}'::jsonb, '{"correctOrderIds":["provision","register","health_check","traffic"]}'::jsonb),

  ('mission-be22-08-o1-c1', 'mission-be22-08-o1', 1, 'code_debugging', 'This service is about to be scaled out to three instances. Which line is the reason a user''s cart will randomly disappear once that happens?', '{"language":"typescript","code":"const sessions = new Map();\n\napp.post(\"/checkout\", (req, res) => {\n  const userId = req.user.id;\n  sessions.set(userId, req.body.cart);\n  res.json({ ok: true });\n});\n\napp.get(\"/cart\", (req, res) => {\n  const cart = sessions.get(req.user.id);\n  res.json({ cart });\n});","question":"This service is about to be scaled out to three instances. Which line is the reason a user''s cart will randomly disappear once that happens?"}'::jsonb, '{"requiredLineIds":["const sessions = new Map();"]}'::jsonb),
  ('mission-be22-08-o2-c1', 'mission-be22-08-o2', 1, 'multiple_choice', 'What is the actual fix that lets this service scale out safely?', '{"question":"What is the actual fix that lets this service scale out safely?","options":[{"id":"a","text":"Add sticky sessions so each user always hits the same instance, permanently"},{"id":"b","text":"Move the session and cart data out of local memory into a shared store (e.g. Redis, the database) that every instance can read and write"},{"id":"c","text":"Just do not scale past one instance"},{"id":"d","text":"Cache the cart in the response headers instead"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be22-09-o1-c1', 'mission-be22-09-o1', 1, 'drag_and_drop', 'Match each load balancing algorithm to what it actually does.', '{"items":[{"id":"i1","text":"Round robin"},{"id":"i2","text":"Least connections"},{"id":"i3","text":"IP hash"}],"targets":[{"id":"t1","label":"Sends each new request to the next instance in a fixed rotation, one after another"},{"id":"t2","label":"Sends each new request to whichever instance currently has the fewest active connections"},{"id":"t3","label":"Sends all requests from the same client IP to the same instance, consistently"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),

  ('mission-be22-10-o1-c1', 'mission-be22-10-o1', 1, 'investigation', 'Instance-3 is clearly failing. Why is the load balancer still sending it a third of all traffic?', '{"evidence":[{"id":"ev1","label":"Load balancer traffic distribution","detail":"instance-3 receiving 33% of requests, same as instance-1 and instance-2"},{"id":"ev2","label":"instance-3 error rate","detail":"94% of its requests returning 500 for the last six minutes"},{"id":"ev3","label":"Health check configuration on the load balancer","detail":"None configured for this service"}],"question":"Instance-3 is clearly failing. Why is the load balancer still sending it a third of all traffic?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be22-11-o1-c1', 'mission-be22-11-o1', 1, 'multiple_choice', 'Normal peak is 500 concurrent users, each generating roughly 2 requests/sec. One instance can sustainably handle 400 requests/sec. Planning for a 5x traffic spike with 30% headroom on top of that, how many instances are actually needed?', '{"question":"Normal peak is 500 concurrent users, each generating roughly 2 requests/sec on average. One instance can sustainably handle 400 requests/sec. Planning for a 5x traffic spike with 30% headroom above that, how many instances are actually needed?","options":[{"id":"a","text":"3 instances"},{"id":"b","text":"17 instances -- accounting for the 5x spike and 30% headroom on top of it, not just today''s normal load"},{"id":"c","text":"1,000 instances"},{"id":"d","text":"Instances are not relevant to capacity planning"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be22-12-o1-c1', 'mission-be22-12-o1', 1, 'investigation', 'Which evidence actually points at the root cause of the checkout failures, not just a symptom of the incident?', '{"evidence":[{"id":"ev1","label":"Instance CPU/memory graphs across all 12 replicas","detail":"Normal, no resource exhaustion on any instance"},{"id":"ev2","label":"User reports","detail":"Carts and login sessions randomly disappear, correlated with which instance handled the user''s most recent request"},{"id":"ev3","label":"Load balancer algorithm","detail":"Round robin, functioning as configured"}],"question":"Which evidence actually points at the root cause of the checkout failures, not just a symptom of the incident?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be22-12-o2-c1', 'mission-be22-12-o2', 1, 'multiple_choice', 'Before finding the real cause, three fixes were on the table. Which one actually addresses a per-instance local-memory state problem?', '{"question":"Before finding the real cause, three fixes were on the table. Which one actually addresses a per-instance local-memory state problem?","options":[{"id":"a","text":"Buy an even bigger box and go back to a single instance"},{"id":"b","text":"Add more replicas without changing anything else"},{"id":"c","text":"Cache everything more aggressively at the edge"},{"id":"d","text":"Move session and cart state out of each instance''s local memory into a shared store every instance can read and write"}]}'::jsonb, '{"correctOptionId":"d"}'::jsonb),
  ('mission-be22-12-o3-c1', 'mission-be22-12-o3', 1, 'code_debugging', 'This patch shipped and the bug is still happening. Which line is still the actual problem?', '{"language":"typescript","code":"const sessions = new LocalCache({ maxSize: 10000 });\n\napp.post(\"/checkout\", (req, res) => {\n  const userId = req.user.id;\n  sessions.set(userId, req.body.cart);\n  res.json({ ok: true });\n});\n\napp.get(\"/cart\", (req, res) => {\n  const cart = sessions.get(req.user.id);\n  res.json({ cart });\n});","question":"This patch shipped and the bug is still happening. Which line is still the actual problem?"}'::jsonb, '{"requiredLineIds":["const sessions = new LocalCache({ maxSize: 10000 });"]}'::jsonb),
  ('mission-be22-12-o4-c1', 'mission-be22-12-o4', 1, 'boss_encounter', 'Synthesize the incident: state the actual root cause and the fix, not any of the tempting workarounds.', '{"stages":[{"objectiveRef":"mission-be22-12-o1","label":"Diagnose the failure"},{"objectiveRef":"mission-be22-12-o2","label":"Reject the wrong fixes"},{"objectiveRef":"mission-be22-12-o3","label":"Confirm the fix holds"}],"task":"Synthesize the incident: horizontal scaling did not cause the failure -- it exposed a service that stored per-user session and cart state in local memory instead of a shared store every instance can reach. State that as the root cause and the fix."}'::jsonb, '{"requiredObjectiveIds":["mission-be22-12-o1","mission-be22-12-o2","mission-be22-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be22-01-o1-c1', 'orientation', 'Ask whether the server ever actually stopped answering.', 10, 1),
  ('mission-be22-01-o1-c1', 'solution', 'It returned 200 OK -- the server never went down. This is elevated latency: the request completed, just slowly.', 20, 2),
  ('mission-be22-01-o2-c1', 'orientation', 'Only one of these four steps is where the server actually does "the work" -- the other three are all travel or waiting.', 10, 1),
  ('mission-be22-01-o2-c1', 'solution', 'Out to the server, then queueing, then processing, then back to the client -- each step is a distinct place latency can accumulate.', 20, 2),

  ('mission-be22-02-o1-c1', 'orientation', 'Per-request processing time and total wait time are two different numbers -- one changed here and one did not.', 10, 1),
  ('mission-be22-02-o1-c1', 'concept', 'Once a system is handling as many requests at once as it can, new requests do not get processed slower -- they wait for room, and that wait is what shows up as latency.', 20, 2),
  ('mission-be22-02-o1-c1', 'solution', 'Processing time held steady at roughly 200ms. What grew was how long requests queued waiting for capacity -- that is a throughput ceiling, not a per-request slowdown.', 30, 3),
  ('mission-be22-02-o2-c1', 'orientation', 'Look for the metric that actually moved during the incident, not the ones that stayed flat.', 10, 1),
  ('mission-be22-02-o2-c1', 'solution', 'ev2 -- requests-in-flight climbing from 40 to 3,800 is the throughput ceiling being hit; processing time and TLS versions never changed.', 20, 2),

  ('mission-be22-03-o1-c1', 'orientation', 'A percentile tells you about a slice of requests, not the whole distribution at once.', 10, 1),
  ('mission-be22-03-o1-c1', 'concept', 'p99 means 99% of requests were at least that fast -- the remaining 1% is exactly the tail an average buries.', 20, 2),
  ('mission-be22-03-o1-c1', 'solution', '9,200ms at p99 is real: at meaningful volume, that "1%" is thousands of actual people, which the 340ms average never shows you.', 30, 3),
  ('mission-be22-03-o2-c1', 'orientation', 'The support queue complaints are coming from a minority of users, not the typical one.', 10, 1),
  ('mission-be22-03-o2-c1', 'solution', 'ev3 -- p99 at 9,400ms is exactly the long tail generating those complaints, invisible in p50 or even p95.', 20, 2),

  ('mission-be22-04-o1-c1', 'orientation', 'Add up each function''s own total, then look for the one child call that swallows almost its entire parent''s time.', 10, 1),
  ('mission-be22-04-o1-c1', 'concept', 'A function''s "total" includes everything it calls -- the real culprit is the deepest line where the time actually got spent, not just the first big number you see.', 20, 2),
  ('mission-be22-04-o1-c1', 'solution', 'queryAttendeesTable -- 7860ms accounts for nearly the entire 8,210ms request; everything else is noise by comparison.', 30, 3),

  ('mission-be22-05-o1-c1', 'orientation', 'CPU-bound looks like a busy processor. I/O-bound looks like an idle one that is stuck waiting.', 10, 1),
  ('mission-be22-05-o1-c1', 'solution', 'ev1 (4% CPU) and ev2 (7,860 of 7,890ms spent waiting on the database) together prove this is I/O-bound, not CPU-bound.', 20, 2),
  ('mission-be22-05-o2-c1', 'orientation', 'Ask what a bigger CPU actually does for a process that is sitting idle, waiting.', 10, 1),
  ('mission-be22-05-o2-c1', 'solution', 'More CPU does not help a wait -- fix what is actually being waited on (the query, the index, the pool, the downstream call).', 20, 2),

  ('mission-be22-06-o1-c1', 'orientation', 'Ask which resource was actually maxed out during the slow request.', 10, 1),
  ('mission-be22-06-o1-c1', 'solution', 'CPU and RAM were never the constraint -- the app server was idle, waiting on the database. Vertical scaling the app server does not touch that wait.', 20, 2),
  ('mission-be22-06-o2-c1', 'orientation', 'Two of these three facts are just costs. One of them is a structural risk that gets worse the more you rely on this approach.', 10, 1),
  ('mission-be22-06-o2-c1', 'solution', 'ev2 -- one instance serving 100% of production traffic means the whole service has a single point of failure, and vertical scaling makes losing that box more costly, not less.', 20, 2),

  ('mission-be22-07-o1-c1', 'orientation', 'Vertical scaling never had to ask whether two boxes could substitute for each other -- there was only ever one box.', 10, 1),
  ('mission-be22-07-o1-c1', 'solution', 'Horizontal scaling only works if any instance can answer any request -- which breaks the moment an instance depends on state that only exists on itself.', 20, 2),
  ('mission-be22-07-o2-c1', 'orientation', 'An instance should not receive real traffic before anyone has confirmed it can actually handle it.', 10, 1),
  ('mission-be22-07-o2-c1', 'solution', 'Provision the instance, register it with the load balancer, let it pass its health check, then it starts receiving live traffic.', 20, 2),

  ('mission-be22-08-o1-c1', 'orientation', 'Ask where this data actually lives, and what happens to it if this one process restarts or a different instance gets the next request.', 10, 1),
  ('mission-be22-08-o1-c1', 'concept', 'A Map declared at module scope lives only inside this one running process''s memory -- it is not shared with, or visible to, any other instance.', 20, 2),
  ('mission-be22-08-o1-c1', 'solution', 'const sessions = new Map(); is the root of it -- that in-memory store only exists on whichever single instance happened to handle the checkout.', 30, 3),
  ('mission-be22-08-o2-c1', 'orientation', 'The fix has to make the data visible to every instance, not just tolerate which instance a user happens to land on.', 10, 1),
  ('mission-be22-08-o2-c1', 'solution', 'Move session and cart state into a shared store (Redis, the database) that every instance can read and write -- sticky sessions just hides the problem until an instance dies.', 20, 2),

  ('mission-be22-09-o1-c1', 'orientation', 'One algorithm ignores load entirely and just takes turns; one actively checks current load; one is about keeping the same client on the same instance.', 10, 1),
  ('mission-be22-09-o1-c1', 'solution', 'Round robin rotates in a fixed order, least connections picks the currently least-busy instance, IP hash pins a client consistently to one instance.', 20, 2),

  ('mission-be22-10-o1-c1', 'orientation', 'The load balancer is still splitting traffic evenly -- so what would actually be missing for it to notice instance-3 is broken?', 10, 1),
  ('mission-be22-10-o1-c1', 'solution', 'ev3 -- no health check is configured at all, so the load balancer has no way to know instance-3 is failing and keeps sending it a full share of traffic.', 20, 2),

  ('mission-be22-11-o1-c1', 'orientation', 'Start from today''s normal load, then apply the spike multiplier, then apply the headroom on top of that -- in that order.', 10, 1),
  ('mission-be22-11-o1-c1', 'concept', '500 users * 2 req/sec = 1,000 rps normal. A 5x spike is 5,000 rps. 30% headroom on top of that is 6,500 rps.', 20, 2),
  ('mission-be22-11-o1-c1', 'solution', '6,500 rps needed / 400 rps per instance = 16.25, rounded up to 17 instances.', 30, 3),

  ('mission-be22-12-o1-c1', 'orientation', 'Rule out anything that is just showing the system working as designed, and look for the thing that is actually inconsistent.', 10, 1),
  ('mission-be22-12-o1-c1', 'solution', 'ev2 -- carts and sessions disappearing in a pattern tied to which instance last handled the user is the actual signature of state that is not shared.', 20, 2),
  ('mission-be22-12-o2-c1', 'orientation', 'Two of these options do not touch the data at all; a third makes the same problem worse, not better.', 10, 1),
  ('mission-be22-12-o2-c1', 'concept', 'A bigger box or more replicas without fixing state does not change where the session data lives -- more aggressive caching does not fix consistency, it can make stale data more likely.', 20, 2),
  ('mission-be22-12-o2-c1', 'solution', 'd -- move session and cart state into a shared store every instance can read and write. That is the only option that actually addresses local, per-instance memory.', 30, 3),
  ('mission-be22-12-o3-c1', 'orientation', 'Ask where this "cache" actually lives -- is it shared across every instance, or does each instance still get its own copy?', 10, 1),
  ('mission-be22-12-o3-c1', 'concept', 'An LRU cache created inside one process is still local memory, no matter what it is named -- it solves nothing about state being invisible to other instances.', 20, 2),
  ('mission-be22-12-o3-c1', 'solution', 'const sessions = new LocalCache(...) is still per-instance memory. Naming it a cache did not make it shared -- the fix still has not moved the data anywhere every instance can reach.', 30, 3),
  ('mission-be22-12-o4-c1', 'orientation', 'Look at what all three findings pointed at as one root cause, not three separate problems.', 15, 1),
  ('mission-be22-12-o4-c1', 'solution', 'Horizontal scaling did not cause the failure -- it exposed a service that kept per-user session and cart state in local memory instead of a shared store every instance can reach. Move the state, and any instance can safely handle any request.', 25, 2);
